function useReveal(threshold = 0.18) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.unobserve(node);
        }
      },
      { threshold }
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [threshold]);

  return [ref, visible];
}

function parseStatValue(value) {
  const match = /^(\d+)(K)?(\+|%)?$/i.exec(value.trim());
  if (!match) return { target: 0, unit: "", suffix: value, raw: value };
  const [, num, unit, suffix] = match;
  return { target: parseInt(num, 10), unit: unit ? "K" : "", suffix: suffix || "", raw: value };
}

function useCountUp(target, trigger, duration = 1600) {
  const [value, setValue] = useState(0);
  useEffect(() => {
    if (!trigger) return;
    let start = null;
    let frame;
    const step = (timestamp) => {
      if (start === null) start = timestamp;
      const progress = Math.min((timestamp - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(Math.floor(eased * target));
      if (progress < 1) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [trigger, target, duration]);
  return value;
}

const Reveal = ({ children, className = "", as: Tag = "div" }) => {
  const [ref, visible] = useReveal();
  return (
    <Tag ref={ref} className={`dap-reveal ${visible ? "dap-visible" : ""} ${className}`}>
      {children}
    </Tag>
  );
};

